/* Build Invest Grow: accessible navigation, enquiry choices and honest local preview. */
(function(){
'use strict';
window.SITIO_LISTO=true;
var root=document.documentElement;
root.classList.add('js');
var button=document.querySelector('[data-menu-boton]');
var menu=document.getElementById('menu');
function setupDropdowns(selector){
 document.querySelectorAll(selector).forEach(function(group){
  var closeTimer;
  group.addEventListener('toggle',function(){if(!group.open)return;var siblings=Array.prototype.slice.call(group.parentElement.querySelectorAll(selector));siblings.forEach(function(other){if(other!==group)other.open=false;});});
  var summary=group.querySelector('summary');
  if(summary)summary.addEventListener('click',function(event){if(event.detail>0&&window.matchMedia('(hover: hover) and (pointer: fine)').matches)event.preventDefault();});
  group.addEventListener('pointerenter',function(event){if(event.pointerType==='mouse'){window.clearTimeout(closeTimer);var siblings=Array.prototype.slice.call(group.parentElement.querySelectorAll(selector));siblings.forEach(function(other){other.open=other===group;});}});
  group.addEventListener('pointerleave',function(event){if(event.pointerType==='mouse'){window.clearTimeout(closeTimer);closeTimer=window.setTimeout(function(){group.open=false;},400);}});
 });
}
setupDropdowns('.nav-group');
setupDropdowns('.footer-group');
function closeMenu(restoreFocus){if(!button||!menu)return;button.setAttribute('aria-expanded','false');button.setAttribute('aria-label',root.lang==='es'?'Abrir menú':'Open menu');menu.classList.remove('abierto');document.body.classList.remove('menu-abierto');if(restoreFocus)button.focus();}
if(button&&menu){
button.addEventListener('click',function(){var open=button.getAttribute('aria-expanded')!=='true';button.setAttribute('aria-expanded',String(open));button.setAttribute('aria-label',root.lang==='es'?(open?'Cerrar menú':'Abrir menú'):(open?'Close menu':'Open menu'));menu.classList.toggle('abierto',open);document.body.classList.toggle('menu-abierto',open);if(open)(menu.querySelector('summary, a')||button).focus();});
menu.addEventListener('click',function(e){if(e.target.closest('a'))closeMenu(false);});
document.addEventListener('keydown',function(e){if(!menu.classList.contains('abierto'))return;if(e.key==='Escape'){closeMenu(true);return;}if(e.key==='Tab'){var items=Array.prototype.slice.call(menu.querySelectorAll('summary, details[open] a, :scope > a'));items.push(button);var i=items.indexOf(document.activeElement);if(e.shiftKey&&i===0){e.preventDefault();button.focus();}else if(!e.shiftKey&&document.activeElement===button){e.preventDefault();items[0].focus();}}});
window.addEventListener('resize',function(){if(window.innerWidth>=900)closeMenu(false);});
}
var quiet=window.matchMedia('(prefers-reduced-motion: reduce)').matches;
var reveals=document.querySelectorAll('[data-aparece]');
if(quiet||!('IntersectionObserver' in window)){reveals.forEach(function(el){el.classList.add('visible');});}else{var observer=new IntersectionObserver(function(entries){entries.forEach(function(en){if(en.isIntersecting){en.target.classList.add('visible');observer.unobserve(en.target);}});},{threshold:.06});reveals.forEach(function(el){observer.observe(el);});}

/* Animate the journey when it comes into view; keep the text available throughout. */
var journey=document.querySelector('[data-journey]');
if(journey&&'IntersectionObserver' in window){
 var journeyVisible=false,journeyReduced=window.matchMedia('(prefers-reduced-motion: reduce)');
 journey.dataset.journey='ready';
 function startJourney(){if(journey.dataset.journey==='ready'&&journeyVisible&&!document.hidden&&!journeyReduced.matches)journey.dataset.journey='playing';}
 var journeyObserver=new IntersectionObserver(function(entries){journeyVisible=entries[0].isIntersecting;if(!journeyVisible)journey.dataset.journey='ready';startJourney();},{threshold:.15});
 journey.addEventListener('animationend',function(event){if((event.animationName==='journey-line-x'||event.animationName==='journey-line-y')&&event.target===journey.querySelector('li:last-child .journey-fill'))journey.dataset.journey='done';});
 document.addEventListener('visibilitychange',function(){if(document.hidden&&journey.dataset.journey==='playing')journey.dataset.journey='ready';else startJourney();});
 journeyReduced.addEventListener('change',function(){journey.dataset.journey='ready';startJourney();});
 journeyObserver.observe(journey);
}

/* Lender motion: rotate through every original logo, updating only a hidden face. */
var lenderSection=document.querySelector('[data-lender-section]');
if(lenderSection){
 var motionButton=lenderSection.querySelector('[data-lender-motion]');
 var motionPreference=window.matchMedia('(prefers-reduced-motion: reduce)');
 var directory=lenderSection.querySelector('[data-lender-directory]');
 var artwork=Array.prototype.map.call(directory.querySelectorAll('[data-lender-key]'),function(el){return el.getAttribute('data-lender-class');});
 var nextArtwork=18,userPaused=false,sectionVisible=false;
 directory.open=motionPreference.matches;
 function syncLenderMotion(){lenderSection.dataset.motion=(!userPaused&&!motionPreference.matches&&!directory.open&&sectionVisible&&!document.hidden)?'playing':'paused';motionButton.hidden=motionPreference.matches;motionButton.setAttribute('aria-pressed',String(userPaused));motionButton.textContent=userPaused?'Resume animation':'Pause animation';}
 lenderSection.querySelectorAll('.lender-flipper').forEach(function(flipper){var tile=flipper.parentElement;var halfturn=Number(tile.getAttribute('data-halfturn'))||0;flipper.addEventListener('animationiteration',function(event){if(event.animationName!=='lender-turn')return;halfturn++;var face=halfturn%2===1?flipper.firstElementChild:flipper.lastElementChild;face.querySelector('.lender-mark').className=artwork[nextArtwork%artwork.length];nextArtwork++;});});
 motionButton.addEventListener('click',function(){userPaused=!userPaused;syncLenderMotion();});directory.addEventListener('toggle',syncLenderMotion);
 if('IntersectionObserver' in window){new IntersectionObserver(function(entries){sectionVisible=entries[0].isIntersecting;syncLenderMotion();},{threshold:.05}).observe(lenderSection);}else{sectionVisible=true;}
 motionPreference.addEventListener('change',function(){directory.open=motionPreference.matches;syncLenderMotion();});document.addEventListener('visibilitychange',syncLenderMotion);syncLenderMotion();
}

var validators={validaTelefono:function(value){var t=String(value||'').trim();if(!/^\+?[\d\s().\-]+$/.test(t))return false;var digits=t.replace(/\D/g,'');return digits.length>=8&&digits.length<=15;},validaCorreo:function(value){return /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(String(value||'').trim());}};
window.SITIO_FORM=validators;
var form=document.querySelector('[data-formulario]');
if(!form)return;
var state=form.querySelector('.estado-formulario');
var next=form.querySelector('[name=siguiente]');
var hint=form.querySelector('[data-step-hint]');
var loan=form.querySelector('[name=prestamo]');
var hints={callback:'A conversation about your goals and where to start.',consultation:'Request an appointment. A time must be arranged and confirmed separately.',assessment:'Request an initial discussion of your loan needs. This is not a credit application or approval.'};
next.addEventListener('change',function(){hint.textContent=hints[next.value]||hints.callback;state.textContent='';});
loan.addEventListener('change',function(){state.textContent='';});
document.querySelectorAll('[data-loan]').forEach(function(link){link.addEventListener('click',function(){loan.value=link.getAttribute('data-loan');loan.dispatchEvent(new Event('change'));});});
function mark(field,message){var box=field.closest('.campo');var error=box&&box.querySelector('.error');field.setAttribute('aria-invalid',message?'true':'false');if(error)error.textContent=message||'';}
form.setAttribute('novalidate','');
form.querySelector('[data-enquiry-submit]').disabled=false;
form.addEventListener('input',function(e){if(e.target.hasAttribute('aria-invalid'))mark(e.target,'');state.textContent='';});
form.addEventListener('submit',function(e){
e.preventDefault();
var trap=form.querySelector('[data-trampa] input');
if(trap&&trap.value){state.dataset.tipo='error';state.textContent='This enquiry could not be reviewed. Please leave the hidden field empty.';return;}
var first=null;
form.querySelectorAll('input,select,textarea').forEach(function(field){if(field.closest('[data-trampa]'))return;var value=String(field.value||'').trim();var message='';if(field.required&&((field.type==='checkbox'&&!field.checked)||(field.type!=='checkbox'&&!value)))message=field.type==='checkbox'?'Please confirm your consent.':'Please complete this field.';else if(value&&field.type==='tel'&&!validators.validaTelefono(value))message='Enter a phone number with 8 to 15 digits.';else if(value&&field.type==='email'&&!validators.validaCorreo(value))message='Enter a valid email address.';mark(field,message);if(message&&!first)first=field;});
if(first){state.dataset.tipo='error';state.textContent='Please check the highlighted fields.';first.focus();return;}
/* Delivery is deliberately not implemented until an owner-confirmed destination exists. No network, storage, fake booking or success event. */
state.dataset.tipo='preview';
state.textContent=root.lang==='es'?'Tu consulta sobre '+loan.options[loan.selectedIndex].text.toLowerCase()+' está lista para revisar. Elegiste «'+next.options[next.selectedIndex].text+'». Esta vista previa aún no está conectada; no se ha enviado ni reservado nada.':'Your '+loan.options[loan.selectedIndex].text.toLowerCase()+' enquiry is ready to review. You selected “'+next.options[next.selectedIndex].text+'”. This preview is not connected yet, so nothing has been sent or booked.';
state.setAttribute('tabindex','-1');state.focus();
});
})();

